void LocalCandidatePage::restoreState(const QJsonObject& saved){cancel();if(saved["backgroundMode"]==1&&!host.background){state->setText("背景宿主未接入，未回退读取技术历史。");return;}backgroundBundle={};backgroundDigest.clear();backgroundAccounts.clear();if(saved["backgroundAccounts"].toArray().size()<=100)for(auto v:saved["backgroundAccounts"].toArray())if(v.isString())backgroundAccounts.append(v.toString());{QSignalBlocker guard(backgroundMode);backgroundMode->setCurrentIndex(saved["backgroundMode"]==1?1:0);}result={};namedId.clear();draftHash.clear();selected.clear();auto ids=saved["selected"].toArray();if(ids.size()<=50){QSet<QString> actual;for(auto v:roster)actual.insert(v.toObject()["id"].toString());for(auto v:ids)if(actual.contains(v.toString()))selected.insert(v.toString());}{QSignalBlocker a(strategy),b(group),c(search),d(sort),e(onlyExcluded);strategy->setCurrentIndex(std::clamp(saved["strategy"].toInt(),0,3));search->setText(saved["query"].toString().left(256));sort->setCurrentIndex(std::clamp(saved["sort"].toInt(),0,2));onlyExcluded->setChecked(saved["onlyExcluded"].toBool());title->setText(saved["title"].toString().left(120));if(!saved["groupAll"].toBool(true)){auto index=group->findData(saved["group"].toString());if(index>0)group->setCurrentIndex(index);}}renderScope();renderResult();auto id=saved["namedId"].toString(),anchor=saved["draftHash"].toString(),path=file;if(id.size()>64||anchor.size()>64){state->setText("恢复锚点无效，请显式选择历史。");return;}if(id.isEmpty()&&anchor.isEmpty()){state->setText("已恢复选择；未自动计算或获取数据。");return;}auto bridge=backgroundMode->currentIndex()==1?host.background:nullptr;run([path,id,anchor,bridge](const auto& c){if(bridge){auto out=id.isEmpty()?QJsonObject{{"bundle",bridge->readDraft(anchor,c)},{"draftHash",anchor}}:bridge->read(id,c);out["result"]=out["bundle"].toObject()["result"];return out;}if(!id.isEmpty())return localCandidate::Store(path).read(id,c);return QJsonObject{{"result",localCandidate::Store(path).readDraft(anchor,c)},{"draftHash",anchor}};},[this](auto out){result=out["result"].toObject();backgroundBundle=out["bundle"].toObject();backgroundDigest=out["digest"].toString();namedId=out["id"].toString();draftHash=out["draftHash"].toString();renderResult();state->setText("已只读恢复冻结结果；未重新计算或联网。");},"正在只读恢复上次冻结结果…");}
