 connect(compute,&QPushButton::clicked,this,[this,p,expected,token]{if(token!=generation||!callbackAllowed())return;try{auto raw=p["adapter"].toObject()["input"].toObject();require(localCandidate::canonical(host.snapshot(selected))==localCandidate::canonical(raw["themeSelection"].toObject()["securities"]),"预览后证券版本已变化，请重新选择预览");auto bridge=host.background;run([bridge,p,expected](const auto&c){auto bundle=bridge->completePreview(p,c);auto anchor=bridge->putDraft(bundle,expected,c);return QJsonObject{{"bundle",bundle},{"anchor",anchor}};},[this](auto out){backgroundBundle=out["bundle"].toObject();result=backgroundBundle["result"].toObject();draftHash=out["anchor"].toString();backgroundDigest.clear();namedId.clear();{QSignalBlocker guard(backgroundMode);backgroundMode->setCurrentIndex(1);}renderResult();state->setText("明确主题背景已计算并冻结；选择结果行查看全部原文、版本和计分证据，再命名保存。");},"核对预览来源与草稿版本，计算并冻结…");}catch(const std::exception&e){state->setText(QString::fromUtf8(e.what()));}});
